#pragma once

#include <string>
#include "../Offsets.hpp"
#include "State.hpp"

namespace Decrypt::GNames {

inline std::string GetName(const ReadFn& rd, uint64_t base, uint32_t id, uint32_t xorKey, int depth = 0);

inline uint32_t RecoverPoolKey(const ReadFn& rd, uint64_t base)
{
    const uint64_t chunk = Read<uint64_t>(rd, base + Offsets::GNames + Offsets::NamePoolBlocks);
    if (!PtrOk(chunk))
        return 0;
    const uint16_t header = Read<uint16_t>(rd, chunk + 4);
    const uint32_t len = header >> 1;
    if (len != 4 || (header & 1))
        return 0;
    uint8_t n0[4]{};
    if (!rd(chunk + 6, n0, 4))
        return 0;
    uint32_t key = 0;
    uint8_t* kb = reinterpret_cast<uint8_t*>(&key);
    const char none[] = { 'N', 'o', 'n', 'e' };
    for (int j = 0; j < 4; ++j)
        kb[j] = (uint8_t)(n0[j] ^ (uint8_t)(len & 0xFF) ^ (uint8_t)none[j]);
    if (GetName(rd, base, 0, key) != "None")
        return 0;
    return key;
}

inline uint32_t PoolKey(const ReadFn& rd, uint64_t base)
{
    uint64_t state[7]{};
    const uint32_t seed = Read<uint32_t>(rd, base + Offsets::FNameKey);
    if (seed && rd(base + Offsets::FNameState, state, sizeof(state))) {
        auto try_ptr = [&](uint64_t slot) -> uint32_t {
            if (!PtrOk(slot))
                return 0;
            const uint32_t key = Read<uint32_t>(rd, slot);
            if (!key)
                return 0;
            return GetName(rd, base, 0, key) == "None" ? key : 0;
        };
        uint32_t key = try_ptr(DecodeState(seed, state, StateKind::NameKey));
        if (key)
            return key;
        for (uint32_t i = 0; i < 7; ++i) {
            key = try_ptr(DecodeStateSlot(seed, state, StateKind::NameKey, i));
            if (key)
                return key;
        }
    }
    return RecoverPoolKey(rd, base);
}

inline std::string GetName(const ReadFn& rd, uint64_t base, uint32_t id, uint32_t xorKey, int depth)
{
    if (!xorKey || depth > 8)
        return {};
    const uint64_t chunk = Read<uint64_t>(rd, base + Offsets::GNames + Offsets::NamePoolBlocks + (uint64_t)(id >> 16) * 8);
    if (!PtrOk(chunk))
        return {};
    const uint64_t entry = chunk + (uint64_t)(id & 0xFFFF) * 4;
    const uint16_t header = Read<uint16_t>(rd, entry + 4);
    const uint32_t len = header >> 1;
    const bool wide = (header & 1) != 0;
    if (!len || len > 1024)
        return {};
    const uint32_t bytes = wide ? len * 2 : len;
    uint8_t raw[2048];
    if (bytes > sizeof(raw) || !rd(entry + 6, raw, bytes))
        return {};
    const uint8_t* kb = reinterpret_cast<const uint8_t*>(&xorKey);
    for (uint32_t j = 0; j < len && j < bytes; ++j)
        raw[j] ^= kb[j & 3] ^ (uint8_t)(len & 0xFF);
    std::string s;
    s.reserve(len);
    if (wide) {
        for (uint32_t i = 0; i + 1 < bytes; i += 2) {
            const uint16_t c = (uint16_t)(raw[i] | (raw[i + 1] << 8));
            if (!c)
                break;
            s.push_back((c >= 32 && c < 127) ? (char)c : '?');
        }
    } else {
        for (uint32_t i = 0; i < len; ++i) {
            if (!raw[i])
                break;
            s.push_back((raw[i] >= 32 && raw[i] < 127) ? (char)raw[i] : '?');
        }
    }
    return s;
}

inline std::string GetObjectName(const ReadFn& rd, uint64_t base, uint64_t object, uint32_t xorKey)
{
    const uint32_t id = Read<uint32_t>(rd, object + Offsets::UObject::Name);
    return GetName(rd, base, id, xorKey);
}

}

