#pragma once

#include "../Offsets.hpp"
#include "State.hpp"

namespace Decrypt::GObjects {

constexpr uint32_t ItemSize = 0x18;

struct Table {
    uint64_t header = 0;
    uint64_t chunks = 0;
    int32_t num = 0;
};

inline Table Load(const ReadFn& rd, uint64_t base)
{
    Table t;
    uint64_t state[7]{};
    if (!rd(base + Offsets::GObjectState, state, sizeof(state)))
        return t;
    const uint32_t key = Read<uint32_t>(rd, base + Offsets::GObjectKey);
    if (!key)
        return t;
    t.header = DecodeState(key, state, StateKind::Objects);
    if (!PtrOk(t.header))
        return t;
    t.chunks = Strip(Read<uint64_t>(rd, t.header));
    t.num = Read<int32_t>(rd, t.header + 0x14);
    return t;
}

inline uint64_t GetObject(const ReadFn& rd, const Table& t, int32_t index)
{
    if (index < 0 || index >= t.num || !PtrOk(t.chunks))
        return 0;
    const uint64_t chunk = Read<uint64_t>(rd, t.chunks + (uint64_t)(index >> 16) * 8);
    if (!PtrOk(Strip(chunk)))
        return 0;
    const uint64_t item = Strip(chunk) + (uint64_t)(index & 0xFFFF) * ItemSize;
    const uint64_t obj = Strip(Read<uint64_t>(rd, item));
    return PtrOk(obj) ? obj : 0;
}

}

