#pragma once

#include "../Offsets.hpp"
#include "State.hpp"

namespace Decrypt::GWorld {

inline uint64_t Get(const ReadFn& rd, uint64_t base)
{
    uint64_t state[7]{};
    if (!rd(base + Offsets::GWorldState, state, sizeof(state)))
        return 0;
    const uint32_t key = Read<uint32_t>(rd, base + Offsets::GWorldKey);
    if (!key)
        return 0;
    auto take = [&](uint64_t slot) -> uint64_t {
        if (!PtrOk(slot))
            return 0;
        const uint64_t w = Strip(Read<uint64_t>(rd, slot));
        return PtrOk(w) ? w : 0;
    };
    uint64_t w = take(DecodeState(key, state, StateKind::World));
    if (w)
        return w;
    for (uint32_t i = 0; i < 7; ++i) {
        w = take(DecodeStateSlot(key, state, StateKind::World, i));
        if (w)
            return w;
    }
    return 0;
}

}

rawHeaders.State.hpp:
#pragma once

#include <cstdint>
#include "Common.hpp"

#if defined(_MSC_VER)
#include <intrin.h>
#endif

namespace Decrypt {

inline uint64_t Rol64(uint64_t x, uint32_t n)
{
    n &= 63;
    return n ? ((x << n) | (x >> (64 - n))) : x;
}

inline uint64_t Ror64(uint64_t x, uint32_t n)
{
    return Rol64(x, 0u - n);
}

inline uint64_t SwapBits(uint64_t x, int shift, uint64_t mask)
{
    return (((x << shift) ^ (x >> shift)) & mask) ^ (x >> shift);
}

inline uint64_t Permute(uint64_t x)
{
    x = SwapBits(x, 1, 0xAAAAAAAAAAAAAAAAull);
    x = SwapBits(x, 2, 0xCCCCCCCCCCCCCCCCull);
    x = SwapBits(x, 4, 0xF0F0F0F0F0F0F0F0ull);
    x = SwapBits(x, 8, 0xFF00FF00FF00FF00ull);
    return Ror64(x, 32);
}

inline uint64_t PermuteShift2(uint64_t x)
{
    x = SwapBits(x, 2, 0xCCCCCCCCCCCCCCCCull);
    x = SwapBits(x, 4, 0xF0F0F0F0F0F0F0F0ull);
    x = SwapBits(x, 8, 0xFF00FF00FF00FF00ull);
    return Ror64(x, 32);
}

inline uint64_t MulHi64(uint64_t a, uint64_t b)
{
#if defined(_MSC_VER)
    unsigned __int64 hi = 0;
    (void)_umul128(a, b, &hi);
    return hi;
#else
    return (uint64_t)(((__uint128_t)a * b) >> 64);
#endif
}

inline uint32_t MixKey32(uint32_t key)
{
    uint32_t ebx = key;
    uint32_t ecx = key;
    const uint32_t edx = key;
    ebx <<= 25;
    ecx >>= 15;
    ecx ^= edx;
    ecx >>= 12;
    ebx ^= ecx;
    ebx ^= edx;
    return ebx;
}

inline uint32_t ImulSlotIndex(uint32_t mix)
{
    const uint64_t prod = (uint64_t)mix * 0x2545F4914F6CDD1Dull;
    const uint32_t lo = (uint32_t)prod;
    const uint64_t mulhi = MulHi64(prod, 0x2492492492492493ull);
    uint64_t rax = prod - mulhi;
    rax >>= 1;
    rax += mulhi;
    rax >>= 2;
    rax *= 7;
    return lo - (uint32_t)rax;
}

enum class StateKind { World, Objects, NameKey };

inline uint64_t DecodeStateSlot(uint32_t key, const uint64_t state[7], StateKind kind, uint32_t i)
{
    const uint64_t k = key & 0xFFFFFFFFull;
    const uint64_t mixed =
        ((k ^ ((k ^ (k >> 15)) >> 12) ^ ((k << 25) & 0xFFFFFFFFull)) * 0x2545F4914F6CDD1Dull) & ~0ull;
    const uint32_t high = (uint32_t)(mixed >> 32);
    const uint32_t a = high + i;
    const uint32_t b = high + 2 * i;
    const uint32_t ca = (a % 63) + 1;
    const uint32_t cb = (b % 63) + 1;
    const uint32_t chm = (((high - 1) & 0xFFFFFFFFu) % 63) + 1;
    const uint64_t b64 = (uint64_t)b;
    uint64_t x = state[i] & ~0ull;

    if (kind == StateKind::World) {
        if (i == 0)
            x = (x - 1) & ~0ull;
        else if (i == 1)
            x = Permute(x ^ (~(uint64_t)b));
        else if (i == 2)
            x = Ror64(Ror64(x, cb), ca);
        else if (i == 3)
            x = (~(x ^ (~(uint64_t)b))) & ~0ull;
        else if (i == 4)
            x = x;
        else if (i == 5)
            x = (SwapBits(x, 1, 0xAAAAAAAAAAAAAAAAull) - a) & ~0ull;
        else if (i == 6)
            x = PermuteShift2(x);
    } else if (kind == StateKind::Objects) {
        if (i == 0)
            x = (Permute(x) - high) & ~0ull;
        else if (i == 1)
            x = Permute(Ror64(x, cb));
        else if (i == 2)
            x = (x + i) & ~0ull;
        else if (i == 3)
            x = SwapBits(x ^ (~(uint64_t)b), 1, 0xAAAAAAAAAAAAAAAAull);
        else if (i == 4)
            x = (a + (x ^ (~(uint64_t)b))) & ~0ull;
        else if (i == 5)
            x = (~Permute(x)) & ~0ull;
        else if (i == 6)
            x = (~Ror64(x, cb)) & ~0ull;
    } else {
        if (i == 0)
            x = Permute(Ror64(x, chm));
        else if (i == 1)
            x = Permute(SwapBits(x, 1, 0xAAAAAAAAAAAAAAAAull));
        else if (i == 2)
            x = (Ror64(x, cb) + a) & ~0ull;
        else if (i == 3)
            x = SwapBits((x + b64) & ~0ull, 1, 0xAAAAAAAAAAAAAAAAull);
        else if (i == 4)
            x = Ror64(SwapBits(x, 1, 0xAAAAAAAAAAAAAAAAull), ca);
        else if (i == 5)
            x = Ror64(Permute(x), ca);
        else if (i == 6)
            x = (x ^ a ^ b) & ~0ull;
    }
    return (x ^ k) & ~0ull;
}

inline uint32_t ObjectStateSlot(uint32_t key)
{
    return ImulSlotIndex(MixKey32(key));
}

inline uint64_t DecodeState(uint32_t key, const uint64_t state[7], StateKind kind)
{
    return DecodeStateSlot(key, state, kind, ObjectStateSlot(key));
}

}
